INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('a93440e6eaa64ad1a15f5e4f3ff8ecac','彭汝尊（彭泰荣）',NULL,NULL,NULL,NULL,'','','四川永川','四川','[]','["省级长官", "军长"]','抗日战争时期','汪伪政权','伪任职务：同善社总教主；抗战时期勾结日伪，派遣骨干联络伪满关东军，在四川、西南各省发展道徒，准备伺机武装暴乱接应日军西进抖音百科。。结局：抗战胜利后被捕判刑','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('faeaecefb6e7422da44debed21e3b6aa','彭宝善',NULL,NULL,NULL,NULL,'','','四川永川','四川','[]','["军长"]','抗日战争时期','汪伪政权','伪任职务：彭汝尊次子，亲赴长春拜见溥仪与关东军，带回密令，在四川训练 “神兵” 武装，布置西南地下叛乱网络。。结局：逮捕关押，病死狱中','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('65a619bf8e394daabf635af6c7addb3f','赵毓松',NULL,NULL,NULL,NULL,'','','四川，青年党要人','四川','[]','["部长"]','抗日战争时期','汪伪政权','伪任职务：离开四川赴南京，出任汪伪农矿部长、司法行政部长，汪伪中央高官。。结局：抗战胜利被捕，判处无期徒刑','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('dcbefdc6940d46a1934e8d1a7efee9ab','刘从云（刘神仙）',NULL,NULL,NULL,NULL,'','','四川','四川','[]','[]','抗日战争时期','汪伪政权','伪任职务：四川著名相士、袍哥、会道门大佬；曾私下与汪伪暗通书信，散布抗战悲观投降言论，煽动地方势力动摇。。结局：被国民政府驱逐出川，解放后被镇压','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('fc18adbc84db4ceda821d59bb73ab78d','（额济纳 5 名华人汉奸，档案只记绰号，无完整姓名）',NULL,NULL,NULL,NULL,'','','多为本地商人和驼商','','[]','["特务"]','抗日战争时期','汪伪政权','伪任职务：在额济纳东庙日本特务机关做内应；帮日特采购物资、招募驼队、测绘西北道路水源，充当向导，掩护电台、机场建设，往来银川、酒泉传递情报。。结局：1937 年 7 月被李翰园抓捕，审讯后判刑关押','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('455877b8a674489fb46085d6b60af670','蒋辉若（蒋文焕）',NULL,NULL,NULL,NULL,'','','甘肃临夏，早年在宁夏马福祥部任职','甘肃','[]','["部长", "军长", "司令", "总司令"]','抗日战争时期','伪军','伪任职务：原马家军旧部，包头沦陷后投日，出任伪回军总司令、西北保商督办公署督办；日军计划利用他向西渗透宁夏，策反马鸿逵，在绥远组建伪军武装，威胁宁夏边境。。结局：抗战胜利后被捕，以汉奸罪处决','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('d27b4693dc7c45f0a4aed1b92ce23f74','张阿訇（佚名）',NULL,NULL,NULL,NULL,'','','东北回族，日伪指派的说客','','[]','["军长"]','抗日战争时期','汪伪政权','伪任职务：受关东军派遣，计划潜入银川游说马鸿逵降日，鼓吹所谓 “回民自治”，还携带伪满洲国文书；尚未进入宁夏即被拦截阻止，未能入境黄埔军校同...。。结局：被扣留驱逐，未进入宁夏境内','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('5631f10eacb841d29048a7a1d2f089ee','门致中',NULL,NULL,NULL,NULL,'','','吉林，曾任宁夏省主席（1927‑1929）','吉林','[]','["省级长官", "部长", "军长", "司令", "委员长", "总司令"]','抗日战争时期','华北伪临时政府','伪任职务：早年做过宁夏省主席，抗战期间在华北投敌，伪华北政务委员会常务委员、华北治安军总司令，指挥伪治安军扫荡华北抗日根据地，作恶全部在华北，不在宁夏。。结局：抗战胜利被国民政府收编，之后逃往香港，客死香港','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('7023cd3f9efc489ea0452242e296b296','辜显荣',NULL,NULL,NULL,NULL,'','','台湾鹿港','台湾','[]','["院长", "军长"]','抗日战争时期','汪伪政权','伪任职务：1895 年迎接日军进入台北城，任台北保良总局局长；取得盐、鸦片专卖特权，日本贵族院议员；抗战时期赴大陆鼓吹 “日华亲善”，为日军筹措物资，协助镇压台湾抗日义军抖音百科。。结局：1937 年病死于东京，未等到光复清算','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('18efba2f61a84964ab3008a06e4b853a','谢介石',NULL,NULL,NULL,NULL,'','','台湾新竹','台湾','[]','["部长"]','抗日战争时期','汪伪政权','伪任职务：伪满洲国首任外交部总长，主导伪满外交，大量引荐台湾人赴东北出任伪职，为日本分裂中国效力。。结局：抗战胜利被捕，关押于抚顺战犯管理所，1954 年狱中去世','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('7656e313cae74741bdbd3873ae3c43d6','苏云英',NULL,NULL,NULL,NULL,'','','台湾高雄','台湾','[]','["部长", "军长"]','抗日战争时期','汪伪政权','伪任职务：勾结日军，诱杀抗日义军领袖林少猫及其部众五百余人；把持地方税收，协助殖民当局管控高雄，压榨地方百姓。。结局：1919 年病死，未经历战后审判','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('39dd7d1ea3f4428e99a6a7a0a9f63000','林熊祥',NULL,NULL,NULL,NULL,'','','台湾板桥（板桥林家）','台湾','[]','["军长", "委员长"]','抗日战争时期','汪伪政权','伪任职务：皇民奉公会核心高层；日本投降当夜参与草山 “台湾自治委员会” 阴谋，企图借日军力量搞变相 “独立”，抗拒国民政府接收台湾。。结局：1946 年被捕，判处有期徒刑，后获减刑释放','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('5bf9b5744765483395ff874b2e3c94dd','许丙',NULL,NULL,NULL,NULL,'','','台湾台北','台湾','[]','[]','抗日战争时期','汪伪政权','伪任职务：日据时期台湾金融界巨头，皇民奉公会要员；参与草山阴谋，谋划所谓台湾自治。。结局：战后被捕判刑，获释后经商','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('aed26e295aa3405c9099aef27e2ba528','林景仁',NULL,NULL,NULL,NULL,'','','台湾板桥','台湾','[]','["部长"]','抗日战争时期','汪伪政权','伪任职务：板桥林家，赴伪满洲国任职，伪满外交部政务司欧美科科长，服务伪满傀儡政权。。结局：抗战胜利后被捕，后释放返回台湾','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('b01a170b19004636ba0b9eabcbde217d','谢华辉',NULL,NULL,NULL,NULL,'','','台湾台南','台湾','[]','["委员长"]','抗日战争时期','华北伪临时政府','伪任职务：赴华北沦陷区，出任伪渤海道尹，伪华北政务委员会地方高官，治理沦陷区地方。。结局：战后在北平被捕，多方营救，后获释回台，存在辩护争议。','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('e94ff71954e9461f943fbff2ff333c93','蓝振德',NULL,NULL,NULL,NULL,'','','台湾台南','台湾','[]','["特务"]','抗日战争时期','汪伪政权','伪任职务：长期在大陆沦陷区活动，为日本情报机关工作，从事商贸掩护特务活动，在厦门、上海活动。。结局：福建肃奸时逮捕，审判后获释回台。','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('474e0f4c56f04743b48f3707e193e742','钟壬寿',NULL,NULL,NULL,NULL,'','','台湾','台湾','[]','[]','抗日战争时期','汪伪政权','伪任职务：赴南京汪伪政权，任职汪伪相关机构，作为台籍人员配合日方对东南沿海开展工作，吴浊流《无花果》有记载。。结局：抗战胜利后返回台湾','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('a8a9c2ec48304c7abba9d1c22c7ea6bc','彭盛木',NULL,NULL,NULL,NULL,'','','台湾','台湾','[]','["部长", "军长"]','抗日战争时期','汪伪政权','伪任职务：我方军统潜伏特工，汪伪财政部参事，周佛海日语翻译，为重庆搜集情报，不属于汉奸抖音百科。。结局：身份暴露被捕，受酷刑，保释后伤重去世','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('a37be09654ac4a43acbd4f45962558b6','马选三（马朝选）',NULL,NULL,NULL,NULL,'','','绥远（归绥，今内蒙古）','内蒙古','[]','["军长", "特务"]','抗日战争时期','汪伪政权','伪任职务：包头日本特务机关松井恒白派遣间谍，潜入西宁东关，拉拢地方人员，散布分裂谣言，搜集青海军政情报，策动西北分裂活动。。结局：1938 年在西宁被捕，押解兰州第八战区处置，判处重刑关押','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('615bad9525fc4785abd2bed03f1f9445','白旦迫',NULL,NULL,NULL,NULL,'','','内蒙古','内蒙古','[]','[]','抗日战争时期','汪伪政权','伪任职务：伪装蒙古人潜入青海蒙旗，测绘草原道路水源，煽动蒙古王公脱离国民政府，配合日本西北渗透计划。。结局：被捕后解送兰州审讯判刑','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('62837073eb024dde95993c40dc70c84f','阮志贤',NULL,NULL,NULL,NULL,'','','青海西宁本地人','青海','[]','[]','抗日战争时期','汪伪政权','伪任职务：被日特收买，在西宁开设绸缎商铺作为情报联络点，为潜伏间谍提供掩护，发展本地眼线，收集西宁城防情报。。结局：破获后逮捕，移交第八战区法办','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('5afa906507ea4d4994d5a8593d0067ab','杉荣',NULL,NULL,NULL,NULL,'','','日本籍','','[]','["部长"]','抗日战争时期','汪伪政权','伪任职务：日本派遣特工，潜伏祁连山区，伪装游历者，测绘祁连山地道路，侦察河西走廊运输线路，联络周边游牧部落。。结局：被青海保安处抓获，作为敌侨关押后遣送战俘营','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('7189f1d1672747c9a5860d4d83d7a993','西川一三',NULL,NULL,NULL,NULL,'','','日本籍','','[]','[]','抗日战争时期','汪伪政权','伪任职务：伪装成藏传佛教僧人，长期潜伏塔尔寺一带，搜集西北、西藏方向情报，执行日本西北包围战略计划中国西藏网。。结局：抗战结束被俘，遣返回日本','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
INSERT INTO `Traitors` (`Id`,`Name`,`CourtesyName`,`Pseudonym`,`BirthYear`,`DeathYear`,`BirthYearType`,`DeathYearType`,`NativePlace`,`Province`,`AliasesJson`,`IdentityTagsJson`,`Period`,`Faction`,`Summary`,`RelatedIdsJson`,`CreatedAt`,`UpdatedAt`) VALUES ('2cc10eae6f9846ae95dc05cf766dc91a','某蒙旗札萨克（姓名档案缺失）',NULL,NULL,NULL,NULL,'','','青海海北蒙古王公','青海','[]','["特务"]','抗日战争时期','汪伪政权','伪任职务：秘密和天津日本特务机关书信往来，接受日方礼品，私下传递情报，但不敢公开接受伪职，未公开叛乱。。结局：被青海当局警告管控，未正式司法审判','[]','2026-08-27 21:33:20.000000','2026-08-27 21:33:20.000000');
